def create_categories(apps, schema_editor):
    Category = apps.get_model("bees", "Category")
    Product = apps.get_model("bees", "Product")
    names = dict(DEFAULTS)
    by_slug = {}
    for pos, (slug, name, kids) in enumerate(GROUPS):
        by_slug[slug], _ = Category.objects.get_or_create(slug=slug, defaults={"name": name or names[slug], "position": pos * 10})
        for kpos, kid in enumerate(kids):
            by_slug[kid], _ = Category.objects.get_or_create(slug=kid, defaults={
                "name": names[kid], "parent": by_slug[slug], "position": kpos})
    for slug, name in DEFAULTS:
        Category.objects.get_or_create(slug=slug, defaults={"name": name, "position": 100})
    Category.objects.filter(slug="hoodies", size_chart="").update(size_chart=SIZE_CHART)
    Category.objects.filter(slug="sneakers", size_chart="").update(size_chart=SHOE_CHART)
    # Any other category already used by a product keeps working.
    for slug in Product.objects.values_list("category", flat=True).distinct():
        if slug:
            Category.objects.get_or_create(slug=slug[:30], defaults={"name": slug.replace("-", " ").capitalize(), "position": 200})


